insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4af1893d-9998-48eb-b854-d76a961d685a', 'es', '¿Por qué los cambios de distancia deberían ser graduales y no bruscos?', '["Los movimientos bruscos se sienten invasivos y rompen la complicidad", "Los cambios graduales acompañan el tono emocional que se va creando", "Acercarse rápido siempre indica mucho interés"]'::jsonb, 'Avanzar despacio conserva la sensación de seguridad y te permite leer la situación.')
